    void put(const K& key, const V& value) {
        std::unique_lock<std::shared_mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            // Update existing key
            it->second->second = value;
            usage_list_.splice(usage_list_.begin(), usage_list_, it->second);
