            // Evict least recently used
            auto lru = usage_list_.rbegin();
            cache_.erase(lru->first);
            usage_list_.erase(std::next(lru.base()));
        }
        usage_list_.emplace_front(key, value);
        cache_.emplace(key, usage_list_.begin());
    }

    std::size_t size() const {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        return usage_list_.size();
    }

